SELECT 'SCM_ADM_API_M' AS TBL, T.API_ID
  FROM SCM_MGR.SCM_ADM_API_M T
 WHERE (API_ID LIKE 'DMF0049' || '\_%' ESCAPE '\')
   AND NOT EXISTS (SELECT 1 FROM (SELECT 'DMF0049_main_COLUMN_SETUP' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0049_main_DELETE' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0049_main_EXCEL' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0049_main_FILTER' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0049_main_INSERT' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0049_main_MEASURE_SELECT' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0049_main_SAVE' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0049_main_SEARCH' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0049_main_SORT' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0049_main_SP_VER' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0049_measure_SEARCH' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0049_spreadTitle_SEARCH' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0049_titleSet_SAVE' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0049_titleSet_SEARCH' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0049_unitedVersion_ACTION' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0049_unitedVersion_ACTION_BP' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0049_unitedVersion_SEARCH' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0049_unitedVersion_TITLE' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0049_unitedVersion_TRANSFER' API_ID FROM DUAL) S WHERE NVL(TO_CHAR(T.API_ID), '~') = NVL(TO_CHAR(S.API_ID), '~'));
