  FROM SCM_MGR.SCM_ADM_MNU_BTN_MPG_M T
 WHERE (MNU_ID = 'DMF0049')
   AND NOT EXISTS (SELECT 1 FROM (SELECT 'DMF0049' MNU_ID, 'MDF Reports' SHT_NM, 'COLUMN_SETUP' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0049' MNU_ID, 'MDF Reports' SHT_NM, 'DELETE' MNU_BTN_CD FROM DUAL
