    UNION ALL SELECT 'DMF0049' MNU_ID, 'MDF Reports' SHT_NM, 'MEASURE_SELECT' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0049' MNU_ID, 'MDF Reports' SHT_NM, 'SAVE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0049' MNU_ID, 'MDF Reports' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
