    UNION ALL SELECT 'DMF0049' MNU_ID, 'unitedVersion' SHT_NM, 'TRANSFER' MNU_BTN_CD FROM DUAL) S WHERE NVL(TO_CHAR(T.MNU_ID), '~') = NVL(TO_CHAR(S.MNU_ID), '~') AND NVL(TO_CHAR(T.SHT_NM), '~') = NVL(TO_CHAR(S.SHT_NM), '~') AND NVL(TO_CHAR(T.MNU_BTN_CD), '~') = NVL(TO_CHAR(S.MNU_BTN_CD), '~'));
